            let mut config = load_default_config_for_test(&home).await;
            config.model_provider = ModelProviderInfo {
                name: "rotating relay".to_string(),
                base_url: Some(format!("{}/v1", server.uri())),
                supports_websockets: stateless,
                capabilities: Some(ModelProviderCapabilities {
                    stateless_responses: Some(stateless),
                    ..Default::default()
                }),
                ..Default::default()
            };
            let model = codex_core::test_support::get_model_offline(config.model.as_deref());
            let model_info =
                codex_core::test_support::construct_model_info_offline(&model, &config);
            let thread_id = ThreadId::new();
            let telemetry = SessionTelemetry::new(
                thread_id,
                &model,
                &model_info.slug,
                None,
                None,
                None,
                "test".to_string(),
                false,
                "test".to_string(),
                source.clone(),
            );
            let client = ModelClient::new(
                None,
                AgentIdentityAuthPolicy::JwtOnly,
                thread_id,
                config.model_provider.clone(),
                source.clone(),
                "test".to_string(),
                None,
                false,
                false,
                false,
                false,
                None,
                false,
                None,
                config.http_client_factory(),
                config.workspace_routing_context(),
                Vec::new(),
            );
            assert!(!client.responses_websocket_enabled());
            let metadata = responses_metadata(
                "11111111-1111-4111-8111-111111111111",
                &thread_id.to_string(),
                &thread_id.to_string(),
                None,
                format!("{thread_id}:0"),
                &source,
                None,
                TestCodexResponsesRequestKind::Turn,
            );
            let saved = json!([
                {"type":"message", "id":"msg_saved", "role":"user", "content":[{"type":"input_text", "text":"saved request"}]},
                {"type":"reasoning", "id":"rs_saved", "summary":[], "encrypted_content":"resource-bound-reasoning"},
                {"type":"function_call", "id":"fc_saved", "call_id":"call_saved", "name":"read_file", "arguments":"{}"},
                {"type":"function_call_output", "id":"fco_saved", "call_id":"call_saved", "output":"saved tool result"},
                {"type":"custom_tool_call", "id":"ctc_saved", "call_id":"custom_saved", "name":"apply_patch", "input":"patch", "status":"completed"},
                {"type":"custom_tool_call_output", "id":"cto_saved", "call_id":"custom_saved", "output":"saved patch result"}
            ]);
            let mut prompt = Prompt::default();
            prompt.input = serde_json::from_value(saved)?;
            let original = prompt.input.clone();
            let mut session = client.new_session();
            for turn in 0..2 {
                let before_request = prompt.input.clone();
                let mut stream = session
                    .stream(
                        &prompt,
                        &model_info,
                        &telemetry,
                        None,
                        ReasoningSummary::None,
                        None,
                        &metadata,
                        &InferenceTraceContext::disabled(),
                    )
                    .await?;
                let mut output = Vec::new();
                let mut completed = false;
                while let Some(event) = stream.next().await {
                    match event? {
                        ResponseEvent::OutputItemDone(item) => output.push(item),
                        ResponseEvent::Completed { .. } => completed = true,
                        _ => {}
                    }
                }
                assert!(completed);
                assert_eq!(prompt.input, before_request);
                prompt.input.extend(output);
                if turn == 0 {
                    prompt.input.push(serde_json::from_value(json!({
                        "type":"message", "id":"msg_followup", "role":"user",
                        "content":[{"type":"input_text", "text":"continue on another resource"}]
