            }
            assert_eq!(&prompt.input[..original.len()], original.as_slice());
            let requests = mock.requests();
            assert_eq!(requests.len(), 2);
            for request in requests {
                let body = request.body_json();
                assert_eq!(body["store"], false);
                assert!(body.get("previous_response_id").is_none());
                let input = body["input"].as_array().unwrap();
                assert_eq!(
                    input.iter().any(|item| item["type"] == "reasoning"),
                    !stateless,
                );
                assert_eq!(
                    body["include"],
                    if stateless {
                        json!([])
                    } else {
                        json!(["reasoning.encrypted_content"])
                    },
                );
                let function = input
                    .iter()
                    .find(|item| item["type"] == "function_call")
                    .unwrap();
                assert_eq!(function["call_id"], "call_saved");
                let output = input
                    .iter()
                    .find(|item| item["type"] == "function_call_output")
                    .unwrap();
                assert_eq!(output["call_id"], "call_saved");
                assert_eq!(output["output"], "saved tool result");
                let custom = input
                    .iter()
                    .find(|item| item["type"] == "custom_tool_call")
                    .unwrap();
                assert_eq!(custom["call_id"], "custom_saved");
                let custom_output = input
                    .iter()
                    .find(|item| item["type"] == "custom_tool_call_output")
                    .unwrap();
                assert_eq!(custom_output["call_id"], "custom_saved");
                if stateless {
                    assert!(input.iter().all(|item| item.get("id").is_none()));
                } else {
                    assert_eq!(function["id"], "fc_saved");
                }
            }
