#[tokio::test]
async fn stateless_responses_is_inherited_by_child_threads_and_tool_followups() -> Result<()> {
    use codex_core::TurnInputRequest;
    use codex_protocol::protocol::EventMsg;
    use codex_protocol::user_input::UserInput;
    use core_test_support::test_codex::test_codex;
    use core_test_support::wait_for_event;

    let server = responses::start_mock_server().await;
    let mut sequence = Vec::new();
    for resource in ["parent", "child"] {
        let mut tool = responses::ev_function_call("call_resource", "unsupported_tool", "{}");
        tool["item"]["id"] = json!(format!("fc_{resource}"));
        sequence.push(responses::sse(vec![
            responses::ev_response_created(&format!("resp_{resource}_a")),
            responses::ev_reasoning_item(&format!("rs_{resource}"), &["summary"], &[]),
            tool,
            responses::ev_completed(&format!("resp_{resource}_a")),
        ]));
        sequence.push(responses::sse(vec![
            responses::ev_assistant_message(&format!("msg_{resource}"), "done"),
            responses::ev_completed(&format!("resp_{resource}_b")),
        ]));
    }
    let mock = responses::mount_sse_sequence(&server, sequence).await;
    let test = test_codex()
        .with_config(|config| {
            config.model_provider.name = "rotating relay".to_string();
            config.model_provider.supports_websockets = true;
            config.model_provider.capabilities = Some(ModelProviderCapabilities {
                stateless_responses: Some(true),
                ..Default::default()
            });
        })
        .build_with_auto_env(&server)
        .await?;
    let mut options = test.start_thread_options().await;
    options.session_source = Some(SessionSource::SubAgent(SubAgentSource::ThreadSpawn {
        parent_thread_id: test.session_configured.thread_id,
        depth: 1,
        agent_path: None,
        agent_nickname: None,
        agent_role: None,
    }));
    let child = test.thread_manager.start_thread(options).await?;
    for thread in [&test.codex, &child.thread] {
        thread
            .start_or_steer_turn(TurnInputRequest::user_input(vec![UserInput::Text {
                text: "run the tool".to_string(),
                text_elements: Vec::new(),
            }]))
            .await?;
        wait_for_event(thread, |event| matches!(event, EventMsg::TurnComplete(_))).await;
    }
    let requests = mock.requests();
    assert_eq!(requests.len(), 4);
    for request in &requests {
        let body = request.body_json();
        assert_eq!(body["store"], false);
        assert_eq!(body["include"], json!([]));
        assert!(
            body["input"]
                .as_array()
                .unwrap()
                .iter()
                .all(|item| { item.get("id").is_none() && item["type"] != "reasoning" })
        );
    }
    for index in [1, 3] {
        let body = requests[index].body_json();
        let input = body["input"].as_array().unwrap();
        assert!(input.iter().any(|item| {
            item["type"] == "function_call_output" && item["call_id"] == "call_resource"
        }));
    }
    Ok(())
}

